style.css:
@-moz-document url-prefix("https://www.TU-PAGINA-AQUI.com") {
/* Fondo general */
body {
    background: linear-gradient(135deg, #a200ff, #5f00ff, #c400ff);
    background-attachment: fixed;
    color: #f7e6ff !important;
    font-family: 'Poppins', sans-serif !important;
}

/* Tarjetas o cajas */
div, section, article {
    background: rgba(0,0,0,0.25) !important;
    backdrop-filter: blur(10px);
    border-radius: 14px !important;
    border: 1px solid rgba(255, 0, 255, 0.25) !important;
}

/* Texto */
p, span, a, li {
    color: #ffe6ff !important;
}

/* Títulos */
h1, h2, h3 {
    color: #ffb3ff !important;
    text-shadow: 0 0 8px #cc00ff;
}

/* Botones */
button {
    background: #b300ff !important;
    color: white !important;
    border-radius: 10px !important;
    border: none !important;
    padding: 10px 20px !important;
    box-shadow: 0 0 12px #cc00ff;
    transition: 0.3s;
}

button:hover {
    background: #e300ff !important;
    box-shadow: 0 0 20px #ff00ff;
}

/* Scrollbar */
::-webkit-scrollbar {
    width: 10px;
}

::-webkit-scrollbar-thumb {
    background: #c000ff;
    border-radius: 10px;
}

::-webkit-scrollbar-track {
    background: #2d003d;
}
}
